$chapters = @"

,  {"id":"SAT-10-16-01","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"To find the mean of a data set, you:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"add all values and divide by count"},{"id":"b","text":"find the middle value"},{"id":"c","text":"find the most common"},{"id":"d","text":"find the range"}],"correctOptionId":"a","explanation":"Mean = sum of all values / number of values.","difficulty":"Easy"},
  {"id":"SAT-10-16-02","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"The median of 3, 5, 7, 9, 11 is:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"7"},{"id":"b","text":"5"},{"id":"c","text":"9"},{"id":"d","text":"6"}],"correctOptionId":"a","explanation":"Middle value of ordered data is 7.","difficulty":"Easy"},
  {"id":"SAT-10-16-03","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"Mode is:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"most frequent value"},{"id":"b","text":"middle value"},{"id":"c","text":"average"},{"id":"d","text":"largest value"}],"correctOptionId":"a","explanation":"Mode is the value that appears most frequently.","difficulty":"Easy"},
  {"id":"SAT-10-16-04","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"Range of data: 5, 8, 12, 15, 20 is:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"15"},{"id":"b","text":"10"},{"id":"c","text":"20"},{"id":"d","text":"12"}],"correctOptionId":"a","explanation":"Range = 20 - 5 = 15.","difficulty":"Easy"},
  {"id":"SAT-10-16-05","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"A bar graph is best for:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"comparing categories"},{"id":"b","text":"showing trends"},{"id":"c","text":"showing proportions"},{"id":"d","text":"showing distribution"}],"correctOptionId":"a","explanation":"Bar graphs effectively compare different categories.","difficulty":"Easy"},
  {"id":"SAT-10-16-06","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"What does the y-intercept represent?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"starting value when x = 0"},{"id":"b","text":"rate of change"},{"id":"c","text":"maximum value"},{"id":"d","text":"minimum value"}],"correctOptionId":"a","explanation":"The y-intercept shows the value when x equals zero.","difficulty":"Easy"},
  {"id":"SAT-10-16-07","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"Data set: 2, 4, 4, 6, 8. Mode is:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"4"},{"id":"b","text":"6"},{"id":"c","text":"5"},{"id":"d","text":"8"}],"correctOptionId":"a","explanation":"4 appears most frequently (twice).","difficulty":"Easy"},
  {"id":"SAT-10-16-08","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"To read a pie chart, you look at:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"slice sizes"},{"id":"b","text":"line lengths"},{"id":"c","text":"bar heights"},{"id":"d","text":"data points"}],"correctOptionId":"a","explanation":"Pie charts show proportions through slice sizes.","difficulty":"Easy"},
  {"id":"SAT-10-16-09","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"A frequency table shows:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"how often each value occurs"},{"id":"b","text":"trends over time"},{"id":"c","text":"proportions"},{"id":"d","text":"correlations"}],"correctOptionId":"a","explanation":"Frequency tables count occurrences of each value.","difficulty":"Easy"},
  {"id":"SAT-10-16-10","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"The mean of 10, 20, 30 is:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"20"},{"id":"b","text":"15"},{"id":"c","text":"25"},{"id":"d","text":"30"}],"correctOptionId":"a","explanation":"Mean = (10+20+30)/3 = 60/3 = 20.","difficulty":"Easy"},
  {"id":"SAT-10-16-11","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"Which measure is best for skewed data?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"median"},{"id":"b","text":"mean"},{"id":"c","text":"mode"},{"id":"d","text":"range"}],"correctOptionId":"a","explanation":"The median is resistant to outliers and skewness.","difficulty":"Medium"},
  {"id":"SAT-10-16-12","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"IQR measures:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"spread of middle 50%"},{"id":"b","text":"total spread"},{"id":"c","text":"central tendency"},{"id":"d","text":"most common value"}],"correctOptionId":"a","explanation":"IQR = Q3 - Q1, measuring spread of the middle 50%.","difficulty":"Medium"},
  {"id":"SAT-10-16-13","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"A line graph with upward slope shows:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"increasing trend"},{"id":"b","text":"decreasing trend"},{"id":"c","text":"no trend"},{"id":"d","text":"constant"}],"correctOptionId":"a","explanation":"Upward slope indicates an increasing trend.","difficulty":"Medium"},
  {"id":"SAT-10-16-14","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"Data: 5, 10, 15, 20, 25. Median is:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"15"},{"id":"b","text":"10"},{"id":"c","text":"20"},{"id":"d","text":"12.5"}],"correctOptionId":"a","explanation":"Middle value of ordered data is 15.","difficulty":"Medium"},
  {"id":"SAT-10-16-15","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"Percent increase from 50 to 75:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"50%"},{"id":"b","text":"25%"},{"id":"c","text":"33%"},{"id":"d","text":"75%"}],"correctOptionId":"a","explanation":"(75-50)/50 x 100 = 50%.","difficulty":"Medium"},
  {"id":"SAT-10-16-16","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"A scatter plot with points going upward shows:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"positive correlation"},{"id":"b","text":"negative correlation"},{"id":"c","text":"no correlation"},{"id":"d","text":"causation"}],"correctOptionId":"a","explanation":"Upward pattern indicates positive correlation.","difficulty":"Medium"},
  {"id":"SAT-10-16-17","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"Standard deviation measures:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"spread from mean"},{"id":"b","text":"center"},{"id":"c","text":"frequency"},{"id":"d","text":"proportion"}],"correctOptionId":"a","explanation":"Standard deviation measures how spread out data is from the mean.","difficulty":"Medium"},
  {"id":"SAT-10-16-18","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"Outliers affect:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"mean more than median"},{"id":"b","text":"median more than mean"},{"id":"c","text":"both equally"},{"id":"d","text":"neither"}],"correctOptionId":"a","explanation":"The mean is sensitive to outliers; the median is resistant.","difficulty":"Medium"},
  {"id":"SAT-10-16-19","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"Cumulative frequency at a value means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"total count up to that value"},{"id":"b","text":"count at that value"},{"id":"c","text":"percentage"},{"id":"d","text":"average"}],"correctOptionId":"a","explanation":"Cumulative frequency is the running total of frequencies.","difficulty":"Medium"},
  {"id":"SAT-10-16-20","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"To predict y from a trend line y = 2x + 3 when x = 10:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"23"},{"id":"b","text":"20"},{"id":"c","text":"25"},{"id":"d","text":"30"}],"correctOptionId":"a","explanation":"y = 2(10) + 3 = 23.","difficulty":"Medium"},
  {"id":"SAT-10-16-21","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"A box plot shows Q1 = 30, median = 45, Q3 = 60. IQR = ?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"30"},{"id":"b","text":"15"},{"id":"c","text":"45"},{"id":"d","text":"60"}],"correctOptionId":"a","explanation":"IQR = Q3 - Q1 = 60 - 30 = 30.","difficulty":"Hard"},
  {"id":"SAT-10-16-22","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"Correlation of 0.95 means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"very strong positive"},{"id":"b","text":"strong negative"},{"id":"c","text":"weak"},{"id":"d","text":"none"}],"correctOptionId":"a","explanation":"0.95 indicates a very strong positive linear relationship.","difficulty":"Hard"},
  {"id":"SAT-10-16-23","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"Which is a resistant measure?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"median"},{"id":"b","text":"mean"},{"id":"c","text":"range"},{"id":"d","text":"standard deviation"}],"correctOptionId":"a","explanation":"The median is resistant to outliers and extreme values.","difficulty":"Hard"},
  {"id":"SAT-10-16-24","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"A misleading graph might:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"start y-axis at non-zero"},{"id":"b","text":"use appropriate scale"},{"id":"c","text":"label clearly"},{"id":"d","text":"show all data"}],"correctOptionId":"a","explanation":"Starting the y-axis at a non-zero value can exaggerate differences.","difficulty":"Hard"},
  {"id":"SAT-10-16-25","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"Sample mean estimates:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"population mean"},{"id":"b","text":"sample median"},{"id":"c","text":"sample mode"},{"id":"d","text":"sample range"}],"correctOptionId":"a","explanation":"The sample mean is a point estimate of the population mean.","difficulty":"Hard"},
  {"id":"SAT-10-16-26","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"Margin of error:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"accounts for sampling variability"},{"id":"b","text":"indicates bias"},{"id":"c","text":"measures response rate"},{"id":"d","text":"calculates cost"}],"correctOptionId":"a","explanation":"Margin of error quantifies the expected variability in sample statistics.","difficulty":"Hard"},
  {"id":"SAT-10-16-27","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"Data set has mean = 50, SD = 5. Values 40-60 contain approximately:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"95%"},{"id":"b","text":"68%"},{"id":"c","text":"99.7%"},{"id":"d","text":"50%"}],"correctOptionId":"a","explanation":"40-60 is within 2 SDs of mean. By 68-95-99.7 rule, about 95%.","difficulty":"Hard"},
  {"id":"SAT-10-16-28","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"Relative frequency = ?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"frequency / total"},{"id":"b","text":"total / frequency"},{"id":"c","text":"frequency x total"},{"id":"d","text":"frequency - total"}],"correctOptionId":"a","explanation":"Relative frequency = frequency of category / total observations.","difficulty":"Hard"},
  {"id":"SAT-10-16-29","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"Two data sets have same mean but different SDs. The one with larger SD:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"more spread out"},{"id":"b","text":"less spread out"},{"id":"c","text":"same spread"},{"id":"d","text":"more centered"}],"correctOptionId":"a","explanation":"Larger standard deviation indicates greater spread from the mean.","difficulty":"Hard"},
  {"id":"SAT-10-16-30","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 16: Data Interpretation","yearEC":"2024 E.C.","questionText":"P-value less than 0.05 means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"result is statistically significant"},{"id":"b","text":"result is not significant"},{"id":"c","text":"null hypothesis is true"},{"id":"d","text":"effect size is large"}],"correctOptionId":"a","explanation":"P < 0.05 typically indicates statistically significant results.","difficulty":"Hard"},
  {"id":"SAT-10-17-01","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"In a scientific experiment, the independent variable is:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"what is changed"},{"id":"b","text":"what is measured"},{"id":"c","text":"kept constant"},{"id":"d","text":"the result"}],"correctOptionId":"a","explanation":"The independent variable is deliberately changed by the researcher.","difficulty":"Easy"},
  {"id":"SAT-10-17-02","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"The dependent variable:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"is measured in response"},{"id":"b","text":"is changed"},{"id":"c","text":"is controlled"},{"id":"d","text":"is random"}],"correctOptionId":"a","explanation":"The dependent variable is what is measured or observed in response to changes.","difficulty":"Easy"},
  {"id":"SAT-10-17-03","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"A hypothesis:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"can be tested"},{"id":"b","text":"is always true"},{"id":"c","text":"cannot be changed"},{"id":"d","text":"is a fact"}],"correctOptionId":"a","explanation":"A hypothesis is a testable prediction about the relationship between variables.","difficulty":"Easy"},
  {"id":"SAT-10-17-04","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Control variables:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"are kept the same"},{"id":"b","text":"are changed"},{"id":"c","text":"are measured"},{"id":"d","text":"are random"}],"correctOptionId":"a","explanation":"Control variables are kept constant to ensure valid results.","difficulty":"Easy"},
  {"id":"SAT-10-17-05","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"A conclusion should:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"be supported by data"},{"id":"b","text":"contradict data"},{"id":"c","text":"ignore results"},{"id":"d","text":"be assumed"}],"correctOptionId":"a","explanation":"Conclusions must be supported by experimental data and evidence.","difficulty":"Easy"},
  {"id":"SAT-10-17-06","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Scientific method steps include:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"observe, hypothesize, test"},{"id":"b","text":"guess, hope, verify"},{"id":"c","text":"read, write, publish"},{"id":"d","text":"assume, conclude, forget"}],"correctOptionId":"a","explanation":"The scientific method: observe, hypothesize, test, analyze, conclude.","difficulty":"Easy"},
  {"id":"SAT-10-17-07","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"A theory in science:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"is well-supported explanation"},{"id":"b","text":"is a guess"},{"id":"c","text":"is untestable"},{"id":"d","text":"is always wrong"}],"correctOptionId":"a","explanation":"A scientific theory is a well-substantiated explanation supported by evidence.","difficulty":"Easy"},
  {"id":"SAT-10-17-08","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Replication in experiments:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"repeats to verify results"},{"id":"b","text":"copies data"},{"id":"c","text":"fakes results"},{"id":"d","text":"ignores errors"}],"correctOptionId":"a","explanation":"Replication helps verify reliability and validity of results.","difficulty":"Easy"},
  {"id":"SAT-10-17-09","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Graph axes should be:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"labeled clearly"},{"id":"b","text":"left blank"},{"id":"c","text":"hidden"},{"id":"d","text":"colorful only"}],"correctOptionId":"a","explanation":"Clear labels help readers understand what is being presented.","difficulty":"Easy"},
  {"id":"SAT-10-17-10","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Results section should:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"present data objectively"},{"id":"b","text":"interpret results"},{"id":"c","text":"draw conclusions"},{"id":"d","text":"introduce topic"}],"correctOptionId":"a","explanation":"Results sections present findings without interpretation.","difficulty":"Easy"},
  {"id":"SAT-10-17-11","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Correlation between A and B means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"A and B are related"},{"id":"b","text":"A causes B"},{"id":"c","text":"B causes A"},{"id":"d","text":"A and B are equal"}],"correctOptionId":"a","explanation":"Correlation shows relationship but not causation.","difficulty":"Medium"},
  {"id":"SAT-10-17-12","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"A confounding variable:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"alters observed relationship"},{"id":"b","text":"strengthens results"},{"id":"c","text":"simplifies analysis"},{"id":"d","text":"confirms hypothesis"}],"correctOptionId":"a","explanation":"Confounding variables are uncontrolled factors that may influence results.","difficulty":"Medium"},
  {"id":"SAT-10-17-13","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Peer review:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"evaluates research quality"},{"id":"b","text":"ignores methodology"},{"id":"c","text":"accepts all papers"},{"id":"d","text":"hides errors"}],"correctOptionId":"a","explanation":"Peer review evaluates methodology, results, and conclusions before publication.","difficulty":"Medium"},
  {"id":"SAT-10-17-14","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Sample bias means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"sample not representative"},{"id":"b","text":"sample too large"},{"id":"c","text":"sample perfect"},{"id":"d","text":"sample random"}],"correctOptionId":"a","explanation":"Sample bias occurs when the sample does not represent the population.","difficulty":"Medium"},
  {"id":"SAT-10-17-15","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Null hypothesis:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"states no effect"},{"id":"b","text":"states effect exists"},{"id":"c","text":"is always true"},{"id":"d","text":"is proven"}],"correctOptionId":"a","explanation":"The null hypothesis states there is no effect or relationship.","difficulty":"Medium"},
  {"id":"SAT-10-17-16","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Double-blind experiment:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"neither subject nor researcher knows groups"},{"id":"b","text":"researcher knows groups"},{"id":"c","text":"subject knows groups"},{"id":"d","text":"nobody knows anything"}],"correctOptionId":"a","explanation":"Double-blind experiments prevent bias from both subjects and researchers.","difficulty":"Medium"},
  {"id":"SAT-10-17-17","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Scientific notation: 3.5 x 10^4 = ?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"35000"},{"id":"b","text":"3500"},{"id":"c","text":"350"},{"id":"d","text":"350000"}],"correctOptionId":"a","explanation":"3.5 x 10^4 = 3.5 x 10000 = 35000.","difficulty":"Medium"},
  {"id":"SAT-10-17-18","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Significant figures in 0.00520:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"3"},{"id":"b","text":"2"},{"id":"c","text":"4"},{"id":"d","text":"5"}],"correctOptionId":"a","explanation":"Leading zeros don't count. 5, 2, 0 are significant. Total = 3.","difficulty":"Medium"},
  {"id":"SAT-10-17-19","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Hypothesis testing conclusion:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"reject or fail to reject null"},{"id":"b","text":"always accept hypothesis"},{"id":"c","text":"prove hypothesis true"},{"id":"d","text":"ignore results"}],"correctOptionId":"a","explanation":"We either reject the null hypothesis or fail to reject it.","difficulty":"Medium"},
  {"id":"SAT-10-17-20","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Meta-analysis:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"combines results from multiple studies"},{"id":"b","text":"ignores previous research"},{"id":"c","text":"uses one study only"},{"id":"d","text":"hides data"}],"correctOptionId":"a","explanation":"Meta-analysis systematically combines results from multiple studies.","difficulty":"Medium"},
  {"id":"SAT-10-17-21","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Effect size measures:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"magnitude of difference"},{"id":"b","text":"sample size"},{"id":"c","text":"significance level"},{"id":"d","text":"cost"}],"correctOptionId":"a","explanation":"Effect size quantifies the practical significance of a finding.","difficulty":"Hard"},
  {"id":"SAT-10-17-22","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Type I error:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"rejecting true null hypothesis"},{"id":"b","text":"failing to reject false null"},{"id":"c","text":"correct decision"},{"id":"d","text":"sampling error"}],"correctOptionId":"a","explanation":"Type I error: rejecting a true null hypothesis (false positive).","difficulty":"Hard"},
  {"id":"SAT-10-17-23","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Type II error:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"failing to reject false null"},{"id":"b","text":"rejecting true null"},{"id":"c","text":"correct rejection"},{"id":"d","text":"correct acceptance"}],"correctOptionId":"a","explanation":"Type II error: failing to reject a false null hypothesis (false negative).","difficulty":"Hard"},
  {"id":"SAT-10-17-24","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Power of a test:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"probability of correctly rejecting false null"},{"id":"b","text":"probability of Type I error"},{"id":"c","text":"sample size"},{"id":"d","text":"significance level"}],"correctOptionId":"a","explanation":"Power = 1 - P(Type II error), the probability of detecting a real effect.","difficulty":"Hard"},
  {"id":"SAT-10-17-25","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Peer review process:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"experts evaluate before publication"},{"id":"b","text":"authors review themselves"},{"id":"c","text":"public votes"},{"id":"d","text":"skip to publication"}],"correctOptionId":"a","explanation":"Peer review involves expert evaluation to ensure quality and validity.","difficulty":"Hard"},
  {"id":"SAT-10-17-26","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 17: Science Passage Analysis","yearEC":"2024 E.C.","questionText":"Reproducibility:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"others can repeat and get same results"},{"id":"b","text":"only original researcher can replicate"},{"id":"c","text":"results change each time"},{"id":"d","text":"data is hidden"}],"correctOptionId":"a","explanation":"Reproducibility means independent researchers can obtain similar results.","difficulty":"Hard"},
